import type { DrawerImplementationProps } from "./drawer.overlay";

import { forwardRef, useEffect, useRef } from "react";
import { clsx } from "clsx";
import { useTheme } from "@theme";
import { useMergeRefs } from "@hooks/use-merge-refs";

import { DrawerClasses, StyledDrawerBody } from "./drawer.styles";
import { useDrawerContext } from "./hooks/use-drawer-context";

export const DrawerPush = forwardRef<HTMLDivElement, DrawerImplementationProps>(
  (
    {
      className,
      position = "start",
      variant = "default",
      padding = true,
      drawerTrigger,
      drawerContent,
      drawerClose,
      // These Radix Dialog.Content event handlers are intentionally destructured
      // and not forwarded. Push mode does not use Radix Portal/Dialog.Content,
      // so these props are no-ops. They are destructured here to prevent unknown
      // prop warnings from being forwarded to the underlying DOM element via {...props}.
      // eslint-disable-next-line @typescript-eslint/no-unused-vars
      onEscapeKeyDown,
      // eslint-disable-next-line @typescript-eslint/no-unused-vars
      onInteractOutside,
      // eslint-disable-next-line @typescript-eslint/no-unused-vars
      onPointerDownOutside,
      // eslint-disable-next-line @typescript-eslint/no-unused-vars
      onOpenAutoFocus,
      // eslint-disable-next-line @typescript-eslint/no-unused-vars
      onCloseAutoFocus,
      ...props
    },
    ref,
  ) => {
    const { open, triggerRef } = useDrawerContext();
    const theme = useTheme();
    const internalRef = useRef<HTMLDivElement>(null);
    const contentRef = useRef<HTMLDivElement>(null);
    const handleRef = useMergeRefs(ref, internalRef);
    const isMounted = useRef(false);

    useEffect(() => {
      if (internalRef.current) {
        if (!open) {
          // If focus is currently inside the drawer, move it back to the trigger
          if (internalRef.current.contains(document.activeElement)) {
            triggerRef?.current?.focus();
          }
          internalRef.current.setAttribute("inert", "true");
        } else {
          internalRef.current.removeAttribute("inert");
          // Only focus if this isn't the initial mount to prevent stealing focus on page load
          if (isMounted.current) {
            const contentElement = internalRef.current.querySelector(
              `.${DrawerClasses.content}`,
            ) as HTMLElement;
            if (contentElement) {
              contentElement.focus({ preventScroll: true });
            } else {
              contentRef.current?.focus({ preventScroll: true });
            }
          }
        }
      }
      isMounted.current = true;
    }, [open, triggerRef]);

    const isVertical = position === "top" || position === "bottom";

    return (
      <>
        {drawerTrigger}
        <StyledDrawerBody
          ref={handleRef}
          aria-hidden={!open}
          className={clsx(DrawerClasses.root, DrawerClasses.body, DrawerClasses.push, className, {
            [DrawerClasses.start]: position === "start",
            [DrawerClasses.end]: position === "end",
            [DrawerClasses.top]: position === "top",
            [DrawerClasses.bottom]: position === "bottom",
          })}
          currentTheme={theme}
          data-state={open ? "open" : "closed"}
          variant={variant}
          {...props}
        >
          <div
            ref={contentRef}
            className={clsx(DrawerClasses.pushContent, {
              [DrawerClasses.padding]: padding,
            })}
            style={{
              minWidth: isVertical ? "100%" : "var(--drawer-width)",
              minHeight: isVertical ? "var(--drawer-height)" : "100%",
            }}
            tabIndex={-1}
          >
            {drawerClose}
            {drawerContent}
          </div>
        </StyledDrawerBody>
      </>
    );
  },
);

DrawerPush.displayName = "DrawerPush";
